mapper.select:
SELECT 
  FROM crd11_excel_code
 WHERE crd11_company_id = #{companyId}
   AND crd11_bank_cd = #{bankCode}
 ORDER BY crd11_seq

mapper.update:
UPDATE crd11_excel_code
   SET crd11_bank_cd       = #{req.bankCode},
       crd11_bank_excel_cd = #{req.bankExcelCode},
       crd11_seq           = #{req.seq},
       crd11_note          = #{req.text}
 WHERE crd11_excel_code_id = #{req.excelCodeId}
   AND crd11_company_id = #{companyId}

mapper.delete:
DELETE FROM crd11_excel_code
 WHERE crd11_company_id = #{companyId}
   AND crd11_excel_code_id IN
#{id}
